(7732379, 1274208, 75585, '<td valign="top">Love this!  The raindrops on your window in all those different colors - is great!</td>', 'Love this!  The raindrops on your window in all those different colors - is great!', '2022-11-09 00:03:42.000000', NULL, 1),
(7732502, 1274206, 30861, '<td valign="top">You call THAT a traffic jam? Jejeje... Around Boston, it''s bumper-to-bumper and barely moving morning and evening. Trying to get to Cape Cod on a weekend, expect it to take 3 hours to get across the bridge from 6 miles out :-) Pfft! Cool picture though.</td>', 'You call THAT a traffic jam? Jejeje... Around Boston, it''s bumper-to-bumper and barely moving morning and evening. Trying to get to Cape Cod on a weekend, expect it to take 3 hours to get across the bridge from 6 miles out :-) Pfft! Cool picture though.', '2022-11-10 18:14:17.000000', NULL, 1),
(7732524, 1274141, 63398, '<td valign="top">I live near places like this. If you can see the line, I''m through it. LOL! 6</td>', 'I live near places like this. If you can see the line, I''m through it. LOL! 6', '2022-11-10 22:42:30.000000', NULL, 1),
(7732527, 1274208, 63398, '<td valign="top">Excellent example of confusing construction detour mayhem. Really nicely seen and captured. I might like it better than my own! LOL! 8</td>', 'Excellent example of confusing construction detour mayhem. Really nicely seen and captured. I might like it better than my own! LOL! 8', '2022-11-10 22:44:55.000000', NULL, 1),
